-- Catalogue fourni : pf2e_huiles_elixirs_potions_AoN.csv (338 références).
-- Import uniquement : aucun inventaire de campagne n'est modifié.
-- Les liens sources sont des pages de catégorie AoN, pas des fiches individuelles.
-- Réexécutable sans doublon. Les prix absents restent NULL.
begin;

alter table public.pf2e_equipment_references
  add column if not exists item_type text,
  add column if not exists level integer check (level is null or level >= 0),
  add column if not exists rarity text;

-- Une page source peut désormais documenter plusieurs objets.
alter table public.pf2e_equipment_references
  drop constraint if exists pf2e_equipment_references_aon_url_key;
create unique index if not exists pf2e_equipment_references_source_name_key
  on public.pf2e_equipment_references (aon_url, name_en);

on conflict (aon_url, name_en) do update set
  source_tab = excluded.source_tab,
  equipment_kind = excluded.equipment_kind,
  price_label = excluded.price_label,
  price_cp = excluded.price_cp,
  item_type = excluded.item_type,
  level = excluded.level,
  rarity = excluded.rarity;

commit;

